<?php require_once __DIR__.'/config.php'; require_admin(); $page_title='User Accounts'; require_once __DIR__.'/header.php'; if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['full_name']??'');$username=trim($_POST['username']??'');$pass=$_POST['password']??'';$role=$_POST['role']??'front_desk';if($name===''||$username===''||strlen($pass)<6){flash('Enter a name, username, and password of at least 6 characters.','error');}else{try{db()->prepare('INSERT INTO users(full_name,username,password,role) VALUES(?,?,?,?)')->execute([$name,$username,password_hash($pass,PASSWORD_DEFAULT),$role]);flash('User account created.');}catch(PDOException $e){flash('That username is already in use.','error');}}header('Location: users.php');exit;} $users=db()->query('SELECT id,full_name,username,role,status,created_at FROM users ORDER BY created_at DESC')->fetchAll();?>
<div class="list-head"><div><span>ADMINISTRATION</span><h2>User accounts</h2><p>People who can access the payment-recording system.</p></div><button class="primary" onclick="document.getElementById('user-modal').showModal()">＋ Add User</button></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>Name</th><th>Username</th><th>Role</th><th>Created</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><strong><?=e($u['full_name'])?></strong></td><td><?=e($u['username'])?></td><td><span class="tag"><?=e($u['role']==='front_desk'?'Front Desk':'Admin')?></span></td><td><?=date('M j, Y',strtotime($u['created_at']))?></td></tr><?php endforeach;?></tbody></table></div></div><dialog id="user-modal"><form method="post" class="modal-form"><div class="modal-title"><h2>Add user</h2><button type="button" onclick="this.closest('dialog').close()">×</button></div><label>Full name<input name="full_name" required></label><label>Username<input name="username" required></label><label>Password<input type="password" name="password" minlength="6" required></label><label>Role<select name="role"><option value="front_desk">Front Desk</option><option value="admin">Admin</option></select></label><div class="form-actions"><button type="button" class="secondary" onclick="this.closest('dialog').close()">Cancel</button><button class="primary">Create account</button></div></form></dialog><?php require __DIR__.'/footer.php';
